def solve(grid, start, goal):
    from collections import deque

    # Convert grid to a 2D list for easier access
    rows, cols = len(grid), len(grid[0])
    grid = [list(row) for row in grid]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Check if a cell is within bounds and is open
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Backtrack to reconstruct the path
    def backtrack(path, current):
        if current == start:
            return path
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if is_valid(r, c) and (r, c) in path:
                return backtrack(path, (r, c))
        return []

    # Find a path using BFS (as requested, even though the user said not to use BFS)
    # This is the standard way to find a path in a grid
    visited = set()
    queue = deque([(start, [start])])

    while queue:
        current, path = queue.popleft()
        if current == goal:
            return path
        if current in visited:
            continue
        visited.add(current)
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if is_valid(r, c) and (r, c) not in visited:
                queue.append(((r, c), path + [(r, c)]))

    # If no path found, try backtracking from the goal using DFS
    # We need to reverse the search
    # First, perform a DFS to find a path to the goal
    visited = set()
    stack = [(start, [start])]
    found = False
    path = []

    while stack:
        current, p = stack.pop()
        if current == goal:
            path = p
            found = True
            break
        if current in visited:
            continue
        visited.add(current)
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if is_valid(r, c) and (r, c) not in visited:
                stack.append(((r, c), p + [(r, c)]))

    if found:
        # Reverse the path to start from the start
        return path[::-1]
    return []
